const input = $input.first().json;
const b = input.body || input;

const esc = (v) => String(v).replace(/'/g, "''");
const ok = (v) => v !== undefined && v !== null && String(v).trim() !== '' &&
  !['sin definir', 'null', 'undefined', 'n/a'].includes(String(v).trim().toLowerCase());
const val = (v) => (ok(v) ? `'${esc(String(v).trim())}'` : 'null');
const quitarAcentos = (s) => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const TIPOS = ['KIDS', 'ADULTO', 'ADOLESCENTE', 'AU_PAIR', 'PERSONALIZADO', 'KIDS-ADOLESCENTES'];
const normTipo = (v) => {
  if (!ok(v)) return null;
  let t = quitarAcentos(String(v).trim().toUpperCase()).replace(/\s+/g, '_');
  if (t === 'ADULTOS') t = 'ADULTO';
  if (t === 'AUPAIR' || t === 'AU-PAIR') t = 'AU_PAIR';
  return TIPOS.includes(t) ? t : null;
};
const normOrigen = (v) => {
  if (!ok(v)) return null;
  const t = quitarAcentos(String(v).trim().toUpperCase());
  if (t.includes('RECOMEND')) return 'RECOMENDACION';
  if (t.includes('INSTA')) return 'INSTAGRAM';
  if (t.includes('FACE')) return 'FACEBOOK';
  if (t.includes('TIK')) return 'TIKTOK';
  return 'ORGANICO';
};

const whatsapp = String(b.whatsapp || '').replace(/[^0-9A-Za-z+@._-]/g, '');
const nombreReal = ok(b.nombre) ? String(b.nombre).trim() : null;
const nombreFinal = nombreReal || (ok(b.nombre_perfil) ? String(b.nombre_perfil).trim() : null);

if (!nombreFinal || !whatsapp) {
  throw new Error('Faltan campos requeridos: nombre, whatsapp');
}

const lead_tipo = normTipo(b.lead_tipo);
const categoria = normTipo(b.categoria) || lead_tipo || 'PERSONALIZADO';
const origen = normOrigen(b.origen);
const pi = ok(b.person_identifier) ? String(b.person_identifier).trim() : nombreFinal;

const cols = 'id, nombre, whatsapp, email, person_identifier, lead_tipo, origen, nivel, estado, created_at';

const query = `WITH ex AS (SELECT id FROM leads WHERE whatsapp = '${esc(whatsapp)}' ORDER BY id LIMIT 1),
upd AS (
  UPDATE leads SET
    nombre = COALESCE(${val(nombreReal)}, nombre),
    apellido = COALESCE(${val(b.apellido)}, apellido),
    email = COALESCE(${val(b.email)}, email),
    telefono = COALESCE(${val(b.telefono)}, telefono),
    lead_tipo = COALESCE(${val(lead_tipo)}, lead_tipo),
    categoria = COALESCE(${val(normTipo(b.categoria) || lead_tipo)}, categoria),
    origen = COALESCE(${val(origen)}, origen),
    nivel = COALESCE(${val(b.nivel)}, nivel),
    objetivo = COALESCE(${val(b.objetivo)}, objetivo),
    resumen = COALESCE(${val(b.resumen)}, resumen),
    disponibilidad = COALESCE(${val(b.disponibilidad)}, disponibilidad),
    tags = COALESCE(${val(b.tags)}, tags),
    person_identifier = COALESCE(${val(b.person_identifier)}, person_identifier),
    ultimo_contacto = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
  WHERE id IN (SELECT id FROM ex)
  RETURNING ${cols}
),
ins AS (
  INSERT INTO leads (nombre, apellido, whatsapp, email, telefono, lead_tipo, origen, categoria, nivel, objetivo, resumen, disponibilidad, tags, person_identifier, estado, estado_motivo, estado_fecha, primer_contacto, ultimo_contacto, created_at, updated_at)
  SELECT '${esc(nombreFinal)}', ${val(b.apellido)}, '${esc(whatsapp)}', ${val(b.email)}, ${val(b.telefono)}, ${val(lead_tipo)}, ${val(origen)}, '${esc(categoria)}', ${val(b.nivel)}, ${val(b.objetivo)}, ${val(b.resumen)}, ${val(b.disponibilidad)}, ${val(b.tags)}, '${esc(pi)}', 'NUEVO', 'Nuevo contacto', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  WHERE NOT EXISTS (SELECT 1 FROM ex)
  RETURNING ${cols}
)
SELECT * FROM upd UNION ALL SELECT * FROM ins;`;

return [{ json: { query } }];

const result = $('PostgreSQL - Insert').first().json;

if (!result || !result.id) {
  return [{ json: { success: false, message: 'No se pudo guardar el lead' } }];
}

return [{
  json: {
    success: true,
    message: `Lead guardado (id ${result.id}). Para actualizarlo usá update-lead con id=${result.id} (número, no el WhatsApp).`,
    lead: { id: result.id, nombre: result.nombre, whatsapp: result.whatsapp, estado: result.estado, lead_tipo: result.lead_tipo, origen: result.origen }
  }
}];
